    /**
     * Method to retrieve the Candidate via CandidateFetchOneSummary
     * @param 	summary CandidateFetchOneSummary 
     * @return 	CandidateFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Candidate getCandidate( CandidateFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "CandidateFetchOneSummary arg cannot be null" );
    	
    	Candidate entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Candidate
        	// --------------------------------------
        	CompletableFuture<Candidate> futureEntity = queryGateway.query(new FindCandidateQuery( new LoadCandidateFilter( summary.getCandidateId() ) ), ResponseTypes.instanceOf(Candidate.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Candidate with id " + summary.getCandidateId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


    /**
     * Method to retrieve a collection of all Candidates
     *
     * @return 	List<Candidate> 
     * @exception ProcessingException Thrown if any problems
     */
    public List<Candidate> getAllCandidate() 
    throws ProcessingException {
        List<Candidate> list = null;

        try {
        	CompletableFuture<List<Candidate>> futureList = queryGateway.query(new FindAllCandidateQuery(), ResponseTypes.multipleInstancesOf(Candidate.class));
        	
        	list = futureList.get();
        }
        catch( Exception exc ) {
            String errMsg = "Failed to get all Candidate";
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return list;
    }


